     8	export function build(g) {
     9	  const fill = (a, b, blk) => g.fill(a, b, blk);
    10	  const open = (x0, y0, z0, x1, y1, z1) => carve(g, [x0, y0, z0], [x1, y1, z1]);
    11	  const pa = (x0, z0, x1, z1) => ({ x0, z0, x1, z1 });
    12	  const hole = (y, pieces) => { for (const [x0, z0, x1, z1] of STACKS) open(x0, y, z0, x1, y, z1); };
    13	
    14	  // ---- brick base y0..2 (plinth under gallery + main block; wing; rear porch base)
    15	  fill([25, 0, 35], [70, 2, 61], "bricks");
    16	  fill([37, 0, 62], [58, 2, 75], "bricks");
    17	  fill([37, 0, 76], [58, 2, 79], "bricks");
    18	  // arched vents on the north face, one per window bay
    19	  for (const x of [28, 34, 40, 54, 60, 66]) {
    20	    g.set(x, 1, 35, "iron_bars");
    21	    for (const dx of [-1, 0, 1]) g.set(x + dx, 2, 35, ...B.stairs("brick", "south", "top"));
    22	  }
    23	
    24	  // ---- outer walls y3..17
    25	  const box = (x0, z0, x1, z1) => {
    26	    fill([x0, 3, z0], [x1, 17, z1], WALL);
    27	    fill([x0 + 1, 3, z0 + 1], [x1 - 1, 17, z1 - 1], "air");
    28	  };
    29	  box(26, 42, 69, 61);
    30	  box(37, 61, 58, 75);
    31	  // main interior was just carved at z61 wing overlap: restore the shared wall z61
    32	  fill([37, 3, 61], [58, 17, 61], WALL);
    33	  // courses on all outer faces: y3, y10 string, y17 plate
    34	  for (const y of [3, 10, 17]) {
    35	    const ring = (x0, z0, x1, z1, skipZ61 = false) => {
    36	      fill([x0, y, z0], [x1, y, z0], Q); fill([x0, y, z1], [x1, y, z1], Q);
    37	      fill([x0, y, z0], [x0, y, z1], Q); fill([x1, y, z0], [x1, y, z1], Q);
    38	    };
    39	    ring(26, 42, 69, 61);
    40	    ring(37, 62, 58, 75);
    41	  }
    42	  fill([38, 10, 61], [57, 10, 61], WALL); // inside the wing the shared wall keeps no outer course
    43	
    44	  // ---- floors and ceilings (chimney stacks stay open)
    45	  const slab = (y, x0, z0, x1, z1, blk) => { fill([x0, y, z0], [x1, y, z1], blk); };
    46	  slab(3, 27, 43, 68, 60, "spruce_planks");
    47	  slab(3, 45, 43, 50, 60, Q);
    48	  slab(3, 38, 62, 57, 74, "spruce_planks");
    49	  slab(10, 27, 43, 68, 60, "oak_planks");
    50	  slab(10, 45, 43, 50, 49, Q);
    51	  slab(10, 51, 51, 51, 52, "oak_planks");
    52	  slab(10, 48, 62, 57, 74, "oak_planks");
    53	  slab(17, 27, 43, 68, 60, WALL);
    54	  slab(17, 38, 62, 57, 74, WALL);
    55	  // P-stair: upper floor open over the stair well (x45..50 z50..59)
    56	  open(45, 10, 50, 50, 10, 59);
    57	  for (const y of [3, 10, 17]) hole(y);
    58	
    59	  // ---- partitions
    60	  const px = (x, z0, z1, y0, y1) => fill([x, y0, z0], [x, y1, z1], WALL);
    61	  const pz = (z, x0, x1, y0, y1) => fill([x0, y0, z], [x1, y1, z], WALL);
    62	  for (const [y0, y1] of [[4, 9], [11, 16]]) {
    63	    px(44, 43, 60, y0, y1); px(51, 43, 60, y0, y1); // hall walls
    64	    pz(50, 27, 43, y0, y1); pz(50, 52, 68, y0, y1);
    65	    pz(53, 27, 43, y0, y1); pz(53, 52, 68, y0, y1);
    66	  }
    67	  // ground rear: stack walls x33..34 and x61..62, x38, pantry/powder
    68	  for (const x of [33, 34, 61, 62]) { px(x, 54, 60, 4, 9); }
    69	  px(38, 54, 60, 4, 9);
    70	  // upper
    71	  px(36, 43, 49, 11, 16); px(64, 43, 49, 11, 16); // bedroom 2|3, master|bath
    72	  px(39, 54, 60, 11, 16); // bedroom 4 | west bath
    73	  px(54, 54, 60, 11, 16); // passage | bedroom 5
    74	  for (const x of [61, 62]) px(x, 54, 60, 11, 16);
    75	  // wing upper
    76	  px(50, 63, 74, 11, 16); pz(63, 51, 57, 11, 16); pz(69, 51, 57, 11, 16);
    77	  // stacks keep their cells free (fill may have crossed them)
    78	  for (const [x0, z0, x1, z1] of STACKS) for (const y of [4, 5, 6, 7, 8, 9, 11, 12, 13, 14, 15, 16]) open(x0, y, z0, x1, y, z1);
