    80	  // ---- interior doorways (air)
    81	  open(44, 4, 46, 44, 6, 47); open(44, 4, 51, 44, 6, 52); open(51, 4, 46, 51, 6, 47); open(51, 4, 51, 51, 6, 52);
    82	  open(44, 11, 46, 44, 13, 47); open(44, 11, 51, 44, 13, 52); open(51, 11, 46, 51, 13, 47); open(51, 11, 51, 51, 13, 52);
    83	  // corridor -> front rooms (z50), ground and upper
    84	  for (const [y0, y1] of [[4, 6], [11, 13]]) {
    85	    for (const x of [29, 40, 54, 66]) open(x, y0, 50, x + 1, y1, 50);
    86	    for (const x of [29]) open(x, y0, 53, x + 1, y1, 53); // guest bedroom / bedroom 4
    87	    open(36, y0, 53, 36, y1, 53);
    88	    open(41, y0, 53, 42, y1, 53);
    89	    open(56, y0, 53, 56, y1, 53);
    90	    open(65, y0, 53, 66, y1, 53);
    91	  }
