    93	  open(52, 11, 53, 54, 13, 53); // upper passage to the wing
    94	  open(64, 11, 46, 64, 13, 47); // master | bath
    95	  open(50, 11, 66, 50, 13, 66); open(50, 11, 72, 50, 13, 72); // wing bedrooms
