   117	    for (let y = 3; y <= 17; y++) g.set(x, y, z, ...B.pillar("quartz_pillar", "y"));
   118	
   119	  // ---- living room cove (full ceiling y17 already laid, so the cove only adds the stepped stairs)
   120	  vaultCove(g, 38, 47, 62, 74, 15);
   121	}
